contract InvMutTest {
    C c;
    address initialOwner;

    constructor(C _c) { c = _c; initialOwner = c.owner(); }

    // send an arbitrary amount to c.go and assert owner unchanged and c balance becomes zero
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to forward");

        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe public owner getter and contract balance. The rule: owner never changes and if call did not revert, c.balance == 0
        address ownerNow = c.owner();
        uint256 balNow = address(c).balance;

        // General rule combining both cases: owner is preserved always; if go did not revert then c balance is zero
        assert(ownerNow == initialOwner && (reverted || balNow == 0));
    }

    receive() external payable {}
}

