contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function; amount is how much Ether to send to c.go
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to send");

        // observe owner before
        address ownerBefore = c.owner();
        // observe balances before
        uint256 balCBefore = address(c).balance;
        uint256 balThisBefore = address(this).balance;

        bool reverted;
        // Call c.go forwarding `amount` wei. Must be a top-level call that can change c.
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        address ownerAfter = c.owner();
        uint256 balCAfter = address(c).balance;
        uint256 balThisAfter = address(this).balance;

        // General property: if the call succeeded, owner unchanged and this contract's balance
        // increased by at least the amount that was held by c before (i.e., c cannot destroy Ether on successful execution).
        // Formulated as: either reverted, or owner unchanged and balThisAfter >= balThisBefore + (balCBefore - balCAfter)
        // Note: balCBefore - balCAfter is the net decrease in c's balance; the test contract should have gained at least that much.
        assert(reverted || (ownerAfter == ownerBefore && balThisAfter >= balThisBefore + (balCBefore - balCAfter)));
    }

    // fallback/receive to accept Ether forwarded from c
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking an amount to forward to c.go
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to send");

        // observe before-values
        address ownerBefore = c.owner();
        uint balBefore = address(c).balance;

        // perform the state-changing call; capture whether it reverted
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        address ownerAfter = c.owner();
        uint balAfter = address(c).balance;
        uint ourBalAfter = address(this).balance;

        // If the call succeeded, owner must be unchanged and this contract must have received at least balBefore - balAfter ETH.
        // If the call reverted, we don't require balance relations (call had no effect).
        if (!reverted) {
            assert(ownerAfter == ownerBefore && ourBalAfter >= (address(this).balance /* note: current balance is ourBalAfter */ - 0) && ourBalAfter >= (balBefore - balAfter));
        } else {
            // On revert, owner must still equal ownerBefore (go should not change owner on revert either)
            assert(ownerAfter == ownerBefore);
        }
    }

    receive() external payable {}
}

